fn pick_inner(step_cost_ns: f64, frame_ns: f64) -> u64 {
    let target = (FRAMING_DOMINATION_RATIO * frame_ns / step_cost_ns).ceil() as u64;
    target.clamp(1, MAX_INNER)
}

