371	/// Time one sample (`inner` back-to-back calls), divide down to a
372	/// per-call value in **picoseconds**, and record it, clamping at
373	/// the histogram bounds — a suspend-inflated or wedged sample
374	/// must not panic a long run ([`warn_invalid`] flags it instead).
375	///
376	/// - The seam dither (a random sub-quantum spin before the timer
377	///   pair, outside the timed interval) stops the run's aggregate
378	///   means from carrying a coherent ±quantum phase bias — up to
379	///   ~±2% on fast benches (see
380	///   notes/design.md#dithering-random-phase-injection).
381	fn record_sample<B: Bench>(
382	    bench: &mut B,
383	    inner: u64,
384	    hist: &mut Histogram<u64>,
385	    dither: &mut Dither,
386	) -> u64 {
387	    dither.spin();
388	    let start = std::time::Instant::now();
389	    for _ in 0..inner {
390	        black_box(bench.step());
391	    }
392	    let elapsed_ps = start.elapsed().as_nanos().saturating_mul(1000);
393	    let per_call_ps = round_elapsed_ps(elapsed_ps, inner);
394	    hist.saturating_record(per_call_ps);
395	    per_call_ps
396	}
