780	/// `inner`); the untrimmed `stdev` is the
781	/// hdrhistogram-native stdev, which includes the ms-scale outliers
782	/// in the tail band. Ends with `WARNING` lines flagging poisoned
783	/// stats when they apply — `suspended_s` comes from
784	/// [`run_adaptive`] (see [`warn_invalid`]).
785	#[allow(clippy::too_many_arguments)]
786	// OK: 8th arg tipped the lint; folding the run outputs into a
787	// struct is the probe-based harness rework (todo), not a
788	// side-effect of this change.
789	pub fn print_report(
790	    name: &str,
791	    outer: u64,
792	    inner: u64,
793	    duration_s: f64,
794	    hist: &Histogram<u64>,
795	    cfg: &RunCfg,
796	    suspended_s: f64,
797	    block_stats: Option<&BlockStats>,
798	) {
799	    // Header line: bench name + logfmt-style metadata. `adj` is the
800	    // apparatus overhead subtracted from each sample downstream.
801	    let adj = cfg.overhead.adjust_per_call_ns(inner);
802	    let total = outer * inner;
803	    let blocks_meta = match block_stats {
804	        Some(b) => format!(" blocks={}", b.blocks),
805	        None => String::new(),
806	    };
807	    println!(
808	        "{name} [duration={:.1}s outer={} inner={} calls={} adj/call={}ns{blocks_meta} labels={}]:",
809	        duration_s,
810	        fmt_commas(outer),
811	        inner,
812	        fmt_commas(total),
813	        fmt_commas_f64(adj, 2),
814	        cfg.band_labels.as_str(),
815	    );
816	
817	    let bounds = bands::boundaries();
818	
819	    // Trim anchor: bands at or above the n2 (p99) boundary are
820	    // the "tail" — excluded from the trimmed stats no matter how
821	    // many finer tail bands subdivide them.
822	    #[allow(clippy::unwrap_used)]
823	    // OK: boundaries() always emits n2 (N_DEPTH >= 2)
824	    let trim_bands = bounds.iter().position(|b| b.zpn == "n2").unwrap();
825	
826	    let n_bands = bounds.len() - 1;
827	    let sample_count = hist.len();
828	
829	    // Accumulate per-band stats by walking recorded histogram buckets.
830	    // Each bucket is assigned to the band containing its midpoint rank.
831	    let mut band_first = vec![u64::MAX; n_bands];
832	    let mut band_last = vec![0u64; n_bands];
833	    let mut band_count = vec![0u64; n_bands];
834	    let mut band_sum = vec![0u128; n_bands];
835	
836	    let mut cumulative = 0u64;
837	    for iv in hist.iter_recorded() {
838	        let value = iv.value_iterated_to();
839	        let count = iv.count_at_value();
840	        let mid_rank = (cumulative as f64 + count as f64 / 2.0) / sample_count as f64;
841	        let idx = band_index(mid_rank, &bounds);
842	        band_first[idx] = band_first[idx].min(value);
843	        band_last[idx] = band_last[idx].max(value);
844	        band_count[idx] += count;
845	        band_sum[idx] += value as u128 * count as u128;
846	        cumulative += count;
847	    }
848	
849	    // Trimmed-stat range label, derived from the populated bands.
850	    let trim_range = trim_range_label(&bounds, &band_count, trim_bands, cfg.band_labels);
851	    let mean_trim_label = format!("mean {trim_range}");
852	    let stdev_trim_label = format!("stdev {trim_range}");
853	
854	    // Build rendered rows: (label, first, last, range, count, mean, adj_mean).
855	    struct BandRow {
856	        label: String,
857	        first: String,
858	        last: String,
859	        range: String,
860	        count: String,
861	        mean: String,
862	        adj_mean: String,
863	    }
864	
865	    let mut rows: Vec<BandRow> = Vec::new();
866	    for i in 0..n_bands {
867	        if band_count[i] == 0 {
868	            continue;
869	        }
870	        let mean_ns = band_sum[i] as f64 / band_count[i] as f64 / PS_PER_NS;
871	        let adj_mean = (mean_ns - adj).max(0.0);
872	        rows.push(BandRow {
873	            label: bounds[i + 1].label(cfg.band_labels),
874	            first: fmt_commas_f64(band_first[i] as f64 / PS_PER_NS, cfg.decimals),
875	            last: fmt_commas_f64(band_last[i] as f64 / PS_PER_NS, cfg.decimals),
876	            range: fmt_commas_f64(
877	                (band_last[i] - band_first[i] + 1) as f64 / PS_PER_NS,
878	                cfg.decimals,
879	            ),
880	            count: fmt_commas(band_count[i]),
881	            mean: fmt_commas_f64(mean_ns, cfg.decimals),
882	            adj_mean: fmt_commas_f64(adj_mean, cfg.decimals),
883	        });
884	    }
885	
886	    // Whole-histogram and trimmed (every band below the n2 ≡ p99
887	    // tail cut) summary values, rendered before the width
888	    // pass so the widths account for them — the untrimmed stdev
889	    // is often wider than any band mean and would otherwise
890	    // overflow its column, shifting its line right.
891	    let hist_mean = hist.mean() / PS_PER_NS;
892	    let hist_adj = (hist_mean - adj).max(0.0);
893	    let hist_mean_s = fmt_commas_f64(hist_mean, cfg.decimals);
894	    let hist_adj_s = fmt_commas_f64(hist_adj, cfg.decimals);
895	    let hist_stdev_s = fmt_commas_f64(hist.stdev() / PS_PER_NS, cfg.decimals);
896	
897	    let trim_count: u64 = band_count[..trim_bands].iter().sum();
898	    let trim = if trim_count > 0 {
899	        let trim_sum: u128 = band_sum[..trim_bands].iter().sum();
900	        let trim_mean = trim_sum as f64 / trim_count as f64 / PS_PER_NS;
901	        let trim_adj = (trim_mean - adj).max(0.0);
902	
903	        // Variance: walk histogram buckets, include only non-tail bands.
904	        let mut trim_var_sum = 0.0f64;
905	        let mut trim_var_count = 0u64;
906	        let mut cum = 0u64;
907	        for iv in hist.iter_recorded() {
908	            let value = iv.value_iterated_to();
909	            let count = iv.count_at_value();
910	            let mid_rank = (cum as f64 + count as f64 / 2.0) / sample_count as f64;
911	            let idx = band_index(mid_rank, &bounds);
912	            if idx < trim_bands {
913	                let diff = value as f64 / PS_PER_NS - trim_mean;
914	                trim_var_sum += diff * diff * count as f64;
915	                trim_var_count += count;
916	            }
917	            cum += count;
918	        }
919	        let trim_stdev = if trim_var_count > 1 {
920	            (trim_var_sum / trim_var_count as f64).sqrt()
921	        } else {
922	            0.0
923	        };
924	
925	        Some((
926	            fmt_commas_f64(trim_mean, cfg.decimals),
927	            fmt_commas_f64(trim_adj, cfg.decimals),
928	            fmt_commas_f64(trim_stdev, cfg.decimals),
929	        ))
930	    } else {
931	        None
932	    };
933	
934	    // Block-replication summary strings, rendered before the
935	    // width pass like the other summary lines.
936	    let block_strs = block_stats.map(|b| {
937	        (
938	            fmt_commas_f64(b.mean_ns, cfg.decimals),
939	            fmt_commas_f64(b.ci95_ns, cfg.decimals),
940	            fmt_commas_f64(b.lsc_ns, cfg.decimals),
941	        )
942	    });
943	
944	    // Column widths from rendered strings — band rows and the
945	    // summary lines that print in the mean/adjusted columns.
946	    let label_w = rows
947	        .iter()
948	        .map(|r| r.label.len())
949	        .max()
950	        .unwrap_or(0)
951	        .max(stdev_trim_label.len());
